BEGIN;
CREATE FUNCTION public.ct_bulk_chest_quote(p_chest_id smallint,p_quantity integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE c public.ct_chest_types;v jsonb;d integer;total bigint;BEGIN IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Choisissez 1 à 100 coffres';END IF;SELECT * INTO c FROM public.ct_chest_types WHERE id=p_chest_id;IF NOT FOUND THEN RAISE EXCEPTION 'Coffre indisponible';END IF;v:=public.ct_chest_quote(c.id,auth.uid());d:=CASE WHEN v->>'offer_id' IS NOT NULL THEN 0 WHEN p_quantity>=100 THEN 5 WHEN p_quantity>=50 THEN 3 WHEN p_quantity>=10 THEN 2 ELSE 0 END;total:=greatest(0,round((v->>'current_price')::numeric*p_quantity*(100-d)/100))::bigint;RETURN jsonb_build_object('version',c.version,'unit_price',(v->>'current_price')::bigint,'offer_id',v->'offer_id','quantity',p_quantity,'discount_percent',d,'gross_total',(v->>'current_price')::bigint*p_quantity,'total',total);END $$;
REVOKE ALL ON FUNCTION public.ct_bulk_chest_quote(smallint,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ct_bulk_chest_quote(smallint,integer) TO anon,authenticated;
DROP FUNCTION public.ct_buy_chests(uuid,integer,smallint,bigint,bigint,uuid);
CREATE FUNCTION public.ct_buy_chests(p_operation_id uuid,p_quantity integer,p_chest_id smallint,p_expected_version bigint,p_expected_price bigint,p_expected_offer_id uuid DEFAULT NULL,p_expected_total bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid;r jsonb;q jsonb:=jsonb_build_object('kind','buy_chests','quantity',p_quantity,'chest_id',p_chest_id,'version',p_expected_version,'price',p_expected_price,'offer',p_expected_offer_id);c public.ct_chest_types;v jsonb;ids text[];i integer;asset uuid;price bigint;offer uuid; n integer; assets jsonb:='[]'; quote jsonb;total bigint;paid bigint;
BEGIN PERFORM pg_advisory_xact_lock(173,8);u:=public.ct_lock_wallet();r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;PERFORM public.ct_check_rate(u);IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Choisissez entre 1 et 100 coffres';END IF;
 SELECT * INTO c FROM public.ct_chest_types WHERE id=p_chest_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Coffre indisponible';END IF;
 v:=public.ct_chest_quote(c.id,u);price:=(v->>'current_price')::bigint;offer:=(v->>'offer_id')::uuid;
 IF NOT coalesce((v->>'available')::boolean,false) THEN RAISE EXCEPTION 'Coffre indisponible : dates, stock ou limite atteinte';END IF;
 IF p_expected_version IS DISTINCT FROM c.version OR p_expected_price IS DISTINCT FROM price OR p_expected_offer_id IS DISTINCT FROM offer THEN RAISE EXCEPTION 'Prix ou offre modifié. Actualisez les coffres.';END IF;
 quote:=public.ct_bulk_chest_quote(c.id,p_quantity);total:=(quote->>'total')::bigint;IF p_expected_total IS DISTINCT FROM total AND (p_expected_total IS NOT NULL OR total<>price*p_quantity) THEN RAISE EXCEPTION 'Le prix du lot a changé. Actualisez et confirmez le nouveau total.';END IF;
 PERFORM id FROM public.ct_titles WHERE available AND(NOT exclusive OR c.allow_exclusive) AND(c.title_pool IS NULL OR id=ANY(c.title_pool)) ORDER BY id FOR SHARE;
 SELECT array_agg(id ORDER BY id) INTO ids FROM public.ct_titles WHERE available AND(NOT exclusive OR c.allow_exclusive) AND(c.title_pool IS NULL OR id=ANY(c.title_pool));
 FOR i IN 1..8 LOOP IF c.weights[i]>0 AND NOT EXISTS(SELECT 1 FROM public.ct_titles WHERE id=ANY(ids) AND rarity=i) THEN RAISE EXCEPTION 'Catalogue du coffre incomplet';END IF;END LOOP;
 IF total>0 THEN PERFORM public.ct_post_credit(u,-total,'chest','chest-buy:'||p_operation_id::text);END IF;
 FOR n IN 1..p_quantity LOOP
 v:=public.ct_chest_quote(c.id,u);
 IF NOT coalesce((v->>'available')::boolean,false) OR (v->>'current_price')::bigint IS DISTINCT FROM price OR (v->>'offer_id')::uuid IS DISTINCT FROM offer THEN RAISE EXCEPTION 'Quantité indisponible : stock, offre ou limite par joueur atteinte. Aucun coffre acheté.';END IF;
 paid:=total/p_quantity+CASE WHEN n<=total%p_quantity THEN 1 ELSE 0 END;
 INSERT INTO public.ct_sealed_chests(user_id,chest_id,name,rarity,weights,title_ids,purchase_price) VALUES(u,c.id,c.name,c.rarity,c.weights,ids,paid) RETURNING id INTO asset;
 INSERT INTO public.ct_chest_purchases(user_id,chest_id,offer_id,asset_id,price_paid,operation_id) VALUES(u,c.id,offer,asset,paid,md5(p_operation_id::text||':'||n::text)::uuid);
 UPDATE public.ct_chest_types SET stock_used=stock_used+1 WHERE id=c.id;IF offer IS NOT NULL THEN UPDATE public.ct_chest_offers SET stock_used=stock_used+1 WHERE id=offer;END IF;
 assets:=assets||to_jsonb(asset);END LOOP;
 r:=jsonb_build_object('ok',true,'sealed_ids',assets,'quantity',p_quantity,'chest_id',c.id,'price_paid',total,'discount_percent',quote->'discount_percent');INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;END $$;

REVOKE ALL ON FUNCTION public.ct_buy_chests(uuid,integer,smallint,bigint,bigint,uuid,bigint) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ct_buy_chests(uuid,integer,smallint,bigint,bigint,uuid,bigint) TO authenticated;
CREATE TABLE public.ct_wholesale_offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES public.ct_profiles(id) ON DELETE CASCADE,chest_id smallint NOT NULL REFERENCES public.ct_chest_types(id),name text NOT NULL,rarity smallint NOT NULL,base_price bigint NOT NULL CHECK(base_price BETWEEN 1 AND 1000000000),tiers jsonb NOT NULL,remaining integer NOT NULL CHECK(remaining BETWEEN 0 AND 1000),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled','sold')),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT(now()+interval '7 days'));
CREATE TABLE public.ct_wholesale_assets(asset_id uuid PRIMARY KEY REFERENCES public.ct_sealed_chests(id),offer_id uuid NOT NULL REFERENCES public.ct_wholesale_offers(id) ON DELETE CASCADE,sold boolean NOT NULL DEFAULT false);
CREATE INDEX ct_wholesale_assets_offer ON public.ct_wholesale_assets(offer_id);CREATE INDEX ct_wholesale_seller ON public.ct_wholesale_offers(seller_id);CREATE INDEX ct_wholesale_chest ON public.ct_wholesale_offers(chest_id);
CREATE TABLE public.ct_wholesale_trades(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,offer_id uuid NOT NULL REFERENCES public.ct_wholesale_offers(id),buyer_id uuid NOT NULL REFERENCES public.ct_profiles(id),seller_id uuid NOT NULL REFERENCES public.ct_profiles(id),quantity integer NOT NULL,unit_price bigint NOT NULL,total bigint NOT NULL,asset_ids uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ct_wholesale_trades_buyer ON public.ct_wholesale_trades(buyer_id);CREATE INDEX ct_wholesale_trades_seller ON public.ct_wholesale_trades(seller_id);CREATE INDEX ct_wholesale_trades_offer ON public.ct_wholesale_trades(offer_id);
ALTER TABLE public.ct_wholesale_offers ENABLE ROW LEVEL SECURITY;ALTER TABLE public.ct_wholesale_assets ENABLE ROW LEVEL SECURITY;ALTER TABLE public.ct_wholesale_trades ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.ct_wholesale_offers,public.ct_wholesale_assets,public.ct_wholesale_trades FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.ct_direct_reserved(p_kind text,p_asset uuid,p_except uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.ct_direct_assets i JOIN public.ct_direct_trades t ON t.id=i.trade_id WHERE i.kind=p_kind AND i.asset_id=p_asset AND t.status='open' AND t.expires_at>now() AND(p_except IS NULL OR t.id<>p_except)) OR(p_kind='chest' AND EXISTS(SELECT 1 FROM public.ct_wholesale_assets a JOIN public.ct_wholesale_offers o ON o.id=a.offer_id WHERE a.asset_id=p_asset AND NOT a.sold AND o.status='active' AND o.expires_at>now()));$$;
CREATE FUNCTION public.ct_wholesale_snapshot(p_admin boolean DEFAULT false,p_before timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid();BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Authentication required';END IF;IF p_admin AND NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;RETURN jsonb_build_object('offers',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT o.id,o.name,o.rarity,o.base_price,o.tiers,o.remaining,o.version,o.seller_id,p.username seller,o.expires_at,o.created_at,o.status FROM public.ct_wholesale_offers o JOIN public.ct_profiles p ON p.id=o.seller_id WHERE (p_before IS NULL OR o.created_at<p_before) AND(p_admin OR (o.status='active' AND o.remaining>0 AND o.expires_at>now() AND public.ct_circle_member(u) AND public.ct_circle_member(o.seller_id) AND NOT EXISTS(SELECT 1 FROM public.ct_suspensions WHERE user_id=o.seller_id))) ORDER BY o.created_at DESC,o.id DESC LIMIT 30)x),'[]'::jsonb),'mine',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT id,name,rarity,base_price,tiers,remaining,status,version,expires_at FROM public.ct_wholesale_offers WHERE seller_id=u ORDER BY created_at DESC LIMIT 30)x),'[]'::jsonb),'history',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT t.id,o.name,t.quantity,t.unit_price,t.total,t.created_at,t.buyer_id=u bought FROM public.ct_wholesale_trades t JOIN public.ct_wholesale_offers o ON o.id=t.offer_id WHERE t.buyer_id=u OR t.seller_id=u ORDER BY t.id DESC LIMIT 50)x),'[]'::jsonb));END $$;
CREATE FUNCTION public.ct_wholesale_command(p_operation_id uuid,p_action text,p_values jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid;r jsonb;q jsonb:=jsonb_build_object('kind','wholesale','action',p_action,'values',p_values);o public.ct_wholesale_offers;c public.ct_sealed_chests;ids uuid[];a uuid;v_quantity integer;v_price bigint;v_total bigint;last_min integer:=1;last_price bigint;item jsonb;v_id uuid;
BEGIN PERFORM pg_advisory_xact_lock(173,8);u:=public.ct_lock_wallet();r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;PERFORM public.ct_check_rate(u);
IF p_action='cancel' THEN SELECT * INTO o FROM public.ct_wholesale_offers WHERE id=(p_values->>'id')::uuid FOR UPDATE;IF o.id IS NULL OR(o.seller_id<>u AND NOT public.ct_is_admin()) THEN RAISE EXCEPTION 'Offre introuvable';END IF;IF o.status='active' THEN UPDATE public.ct_wholesale_offers SET status='cancelled',version=version+1 WHERE id=o.id;END IF;IF o.seller_id<>u THEN IF length(trim(coalesce(p_values->>'reason','')))<8 THEN RAISE EXCEPTION 'Justification requise';END IF;INSERT INTO public.ct_admin_audit_logs(admin_id,action,target,reason,details) VALUES(u,'wholesale_cancel',o.id::text,p_values->>'reason','{}');END IF;
ELSE
 IF NOT public.ct_circle_member(u) THEN RAISE EXCEPTION 'Carte active requise';END IF;IF EXISTS(SELECT 1 FROM public.ct_market_settings WHERE id AND(NOT market_enabled OR wallets_frozen)) THEN RAISE EXCEPTION 'Le marché est suspendu ou figé';END IF;
 IF p_action='create' THEN
 IF(SELECT count(*) FROM public.ct_wholesale_offers WHERE seller_id=u AND status='active' AND expires_at>now())>=20 THEN RAISE EXCEPTION '20 offres de gros actives maximum';END IF;
 IF jsonb_typeof(p_values->'asset_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(p_values->'asset_ids') NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Choisissez entre 1 et 1000 coffres';END IF;
 SELECT array_agg(value::text::uuid) INTO ids FROM jsonb_array_elements_text(p_values->'asset_ids');IF cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids)x) THEN RAISE EXCEPTION 'Exemplaire en double';END IF;
 SELECT * INTO c FROM public.ct_sealed_chests WHERE id=ids[1] AND user_id=u AND opened_at IS NULL;IF c.id IS NULL THEN RAISE EXCEPTION 'Coffre indisponible';END IF;
 v_price:=(p_values->>'price')::bigint;IF v_price IS NULL OR v_price NOT BETWEEN 1 AND 1000000000 THEN RAISE EXCEPTION 'Prix invalide';END IF;last_price:=v_price;
 IF jsonb_typeof(p_values->'tiers') IS DISTINCT FROM 'array' OR jsonb_array_length(p_values->'tiers') NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'Choisissez 1 à 8 paliers';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_values->'tiers') LOOP
 IF (item->>'min') IS NULL OR(item->>'price') IS NULL OR(item->>'min')::integer<=last_min OR(item->>'min')::integer>cardinality(ids) OR(item->>'price')::bigint NOT BETWEEN 1 AND last_price THEN RAISE EXCEPTION 'Paliers croissants en quantité, prix décroissants, dans le stock proposé';END IF;last_min:=(item->>'min')::integer;last_price:=(item->>'price')::bigint;END LOOP;
 FOREACH a IN ARRAY ids LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ct_sealed_chests WHERE id=a AND user_id=u AND opened_at IS NULL AND chest_id=c.chest_id AND name=c.name AND rarity=c.rarity AND weights=c.weights) OR public.ct_direct_reserved('chest',a) OR EXISTS(SELECT 1 FROM public.ct_market_listings WHERE asset_kind='chest' AND asset_id=a AND status='active' AND expires_at>now()) THEN RAISE EXCEPTION 'Un coffre est indisponible ou réservé';END IF;END LOOP;
 DELETE FROM public.ct_wholesale_assets wa USING public.ct_wholesale_offers wo WHERE wa.offer_id=wo.id AND wa.asset_id=ANY(ids) AND(wa.sold OR wo.status<>'active' OR wo.expires_at<=now());
 INSERT INTO public.ct_wholesale_offers(seller_id,chest_id,name,rarity,base_price,tiers,remaining) VALUES(u,c.chest_id,c.name,c.rarity,v_price,p_values->'tiers',cardinality(ids)) RETURNING id INTO v_id;
 INSERT INTO public.ct_wholesale_assets(asset_id,offer_id) SELECT x,v_id FROM unnest(ids)x;
 ELSIF p_action='buy' THEN
 SELECT * INTO o FROM public.ct_wholesale_offers WHERE id=(p_values->>'id')::uuid FOR UPDATE;v_quantity:=(p_values->>'quantity')::integer;
 IF o.id IS NULL OR o.status<>'active' OR o.expires_at<=now() OR o.seller_id=u OR NOT public.ct_circle_member(o.seller_id) OR EXISTS(SELECT 1 FROM public.ct_suspensions WHERE user_id=o.seller_id) OR v_quantity IS NULL OR v_quantity NOT BETWEEN 1 AND o.remaining THEN RAISE EXCEPTION 'Offre ou quantité indisponible';END IF;
 SELECT coalesce((SELECT(t->>'price')::bigint FROM jsonb_array_elements(o.tiers)t WHERE(t->>'min')::int<=v_quantity ORDER BY(t->>'min')::int DESC LIMIT 1),o.base_price) INTO v_price;v_total:=v_price*v_quantity;
 IF(p_values->>'version')::bigint IS DISTINCT FROM o.version OR(p_values->>'expected_total')::bigint IS DISTINCT FROM v_total THEN RAISE EXCEPTION 'Offre modifiée. Vérifiez le nouveau total';END IF;
 IF coalesce((SELECT balance FROM public.ct_diamond_wallets WHERE user_id=u),0)-public.ct_direct_diamonds(u)<v_total THEN RAISE EXCEPTION 'Diamants disponibles insuffisants';END IF;
 SELECT array_agg(x.asset_id) INTO ids FROM(SELECT wa.asset_id FROM public.ct_wholesale_assets wa JOIN public.ct_sealed_chests sc ON sc.id=wa.asset_id WHERE wa.offer_id=o.id AND NOT wa.sold AND sc.user_id=o.seller_id AND sc.opened_at IS NULL ORDER BY wa.asset_id LIMIT v_quantity FOR UPDATE OF wa,sc)x;
 IF cardinality(ids) IS DISTINCT FROM v_quantity THEN RAISE EXCEPTION 'Stock réservé indisponible';END IF;
 PERFORM public.ct_post_diamond(u,-v_total,'market_purchase','wholesale:'||p_operation_id::text);PERFORM public.ct_post_diamond(o.seller_id,v_total,'market_sale','wholesale:'||p_operation_id::text);
 UPDATE public.ct_sealed_chests SET user_id=u WHERE id=ANY(ids);UPDATE public.ct_wholesale_assets SET sold=true WHERE asset_id=ANY(ids);UPDATE public.ct_wholesale_offers SET remaining=remaining-v_quantity,status=CASE WHEN remaining=v_quantity THEN 'sold' ELSE 'active' END,version=version+1 WHERE id=o.id;
 INSERT INTO public.ct_wholesale_trades(offer_id,buyer_id,seller_id,quantity,unit_price,total,asset_ids) VALUES(o.id,u,o.seller_id,v_quantity,v_price,v_total,ids);
 ELSE RAISE EXCEPTION 'Action inconnue';END IF;
END IF;
r:=jsonb_build_object('ok',true,'id',coalesce(v_id,o.id),'quantity',v_quantity,'total',v_total);INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;END $$;
REVOKE ALL ON FUNCTION public.ct_wholesale_snapshot(boolean,timestamptz),public.ct_wholesale_command(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ct_wholesale_snapshot(boolean,timestamptz),public.ct_wholesale_command(uuid,text,jsonb) TO authenticated;
CREATE TABLE public.ct_support_tickets(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.ct_profiles(id) ON DELETE CASCADE,subject text NOT NULL CHECK(length(subject) BETWEEN 3 AND 120),category text NOT NULL CHECK(category IN('market','account','chests','bug','other')),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','answered','closed')),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ct_support_owner ON public.ct_support_tickets(user_id,id DESC);CREATE INDEX ct_support_status ON public.ct_support_tickets(status,id DESC);
CREATE TABLE public.ct_support_messages(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_id bigint NOT NULL REFERENCES public.ct_support_tickets(id) ON DELETE CASCADE,author_id uuid REFERENCES public.ct_profiles(id) ON DELETE SET NULL,is_admin boolean NOT NULL,body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX ct_support_thread ON public.ct_support_messages(ticket_id,id DESC);CREATE INDEX ct_support_author ON public.ct_support_messages(author_id);
ALTER TABLE public.ct_support_tickets ENABLE ROW LEVEL SECURITY;ALTER TABLE public.ct_support_messages ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.ct_support_tickets,public.ct_support_messages FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.ct_support_inbox(p_admin boolean DEFAULT false,p_status text DEFAULT 'all',p_before bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required';END IF;IF p_admin AND NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT t.*,p.username FROM public.ct_support_tickets t JOIN public.ct_profiles p ON p.id=t.user_id WHERE(p_admin OR t.user_id=auth.uid()) AND(p_status='all' OR t.status=p_status) AND(p_before IS NULL OR t.id<p_before) ORDER BY t.id DESC LIMIT 30)x),'[]'::jsonb);END $$;
CREATE FUNCTION public.ct_support_thread(p_ticket bigint,p_before bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE t public.ct_support_tickets;BEGIN SELECT * INTO t FROM public.ct_support_tickets WHERE id=p_ticket AND(user_id=auth.uid() OR public.ct_is_admin());IF t.id IS NULL THEN RAISE EXCEPTION 'Ticket introuvable';END IF;RETURN jsonb_build_object('ticket',to_jsonb(t),'messages',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM(SELECT id,body,is_admin,created_at FROM public.ct_support_messages WHERE ticket_id=t.id AND(p_before IS NULL OR id<p_before) ORDER BY id DESC LIMIT 50)x),'[]'::jsonb));END $$;
CREATE FUNCTION public.ct_support_command(p_operation_id uuid,p_action text,p_values jsonb,p_reason text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid;r jsonb;q jsonb:=jsonb_build_object('kind','support','action',p_action,'values',p_values,'reason',p_reason);t public.ct_support_tickets;v_id bigint;admin boolean:=public.ct_is_admin();BEGIN PERFORM pg_advisory_xact_lock(173,8);u:=public.ct_lock_wallet();r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;PERFORM public.ct_check_rate(u);
IF p_action IN('create','reply') AND length(trim(coalesce(p_values->>'body',''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Votre message doit contenir 1 à 4000 caractères';END IF;
IF p_action='create' THEN
 IF length(trim(coalesce(p_values->>'subject',''))) NOT BETWEEN 3 AND 120 THEN RAISE EXCEPTION 'Sujet requis : 3 à 120 caractères';END IF;
 IF(SELECT count(*) FROM public.ct_support_tickets WHERE user_id=u AND status<>'closed')>=5 THEN RAISE EXCEPTION '5 tickets ouverts maximum';END IF;
 INSERT INTO public.ct_support_tickets(user_id,subject,category) VALUES(u,p_values->>'subject',p_values->>'category') RETURNING id INTO v_id;
 INSERT INTO public.ct_support_messages(ticket_id,author_id,is_admin,body) VALUES(v_id,u,false,p_values->>'body');
ELSE
 SELECT * INTO t FROM public.ct_support_tickets WHERE id=(p_values->>'id')::bigint AND(user_id=u OR admin) FOR UPDATE;IF t.id IS NULL THEN RAISE EXCEPTION 'Ticket introuvable';END IF;
 IF t.version IS DISTINCT FROM(p_values->>'version')::bigint THEN RAISE EXCEPTION 'La discussion a changé. Actualisez.';END IF;
 IF admin AND t.user_id<>u AND length(trim(coalesce(p_reason,'')))<8 THEN RAISE EXCEPTION 'Justification administrateur requise';END IF;
 IF p_action='reply' THEN
 IF t.status='closed' THEN RAISE EXCEPTION 'Rouvrez le ticket avant de répondre';END IF;
 IF(SELECT count(*) FROM public.ct_support_messages WHERE ticket_id=t.id)>=500 THEN RAISE EXCEPTION 'Discussion complète : ouvrez un nouveau ticket';END IF;
 INSERT INTO public.ct_support_messages(ticket_id,author_id,is_admin,body) VALUES(t.id,u,admin,p_values->>'body');UPDATE public.ct_support_tickets SET status=CASE WHEN admin AND t.user_id<>u THEN 'answered' ELSE 'open' END,version=version+1,updated_at=now() WHERE id=t.id;
 ELSIF p_action='status' THEN
 IF p_values->>'status' NOT IN('open','closed') OR p_values->>'status' IS NULL THEN RAISE EXCEPTION 'Statut invalide';END IF;
 IF p_values->>'status'='open' AND t.status='closed' AND(SELECT count(*) FROM public.ct_support_tickets WHERE user_id=t.user_id AND status<>'closed')>=5 THEN RAISE EXCEPTION '5 tickets ouverts maximum';END IF;
 UPDATE public.ct_support_tickets SET status=p_values->>'status',version=version+1,updated_at=now() WHERE id=t.id;
 ELSE RAISE EXCEPTION 'Action inconnue';END IF;
 v_id:=t.id;
 IF admin THEN INSERT INTO public.ct_admin_audit_logs(admin_id,action,target,reason,details) VALUES(u,'support_'||p_action,t.id::text,CASE WHEN length(trim(p_reason))>=8 THEN p_reason ELSE 'Gestion du support' END,jsonb_build_object('ticket_id',t.id));END IF;
END IF;
r:=jsonb_build_object('ok',true,'id',v_id);INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;END $$;
REVOKE ALL ON FUNCTION public.ct_support_inbox(boolean,text,bigint),public.ct_support_thread(bigint,bigint),public.ct_support_command(uuid,text,jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ct_support_inbox(boolean,text,bigint),public.ct_support_thread(bigint,bigint),public.ct_support_command(uuid,text,jsonb,text) TO authenticated;
COMMIT;
